import{_ as o,o as t,c,a2 as a}from"./chunks/framework.Dtl3161T.js";const p=JSON.parse('{"title":"架构债务递减预算","description":"","frontmatter":{},"headers":[],"relativePath":"mango-pmo/baselines/architecture/README.md","filePath":"mango-pmo/baselines/architecture/README.md"}'),d={name:"mango-pmo/baselines/architecture/README.md"};function i(r,e,n,s,l,m){return t(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="架构债务递减预算" tabindex="-1">架构债务递减预算 <a class="header-anchor" href="#架构债务递减预算" aria-label="Permalink to &quot;架构债务递减预算&quot;">​</a></h1><p><code>debt-budget.json</code> 使用 schema v4 记录全 Reactor 架构扫描的全局及逐 Maven 模块规则计数、稳定问题 identity 多重集合。它只豁免已经登记的历史身份，不能豁免当前变更新增、替换或跨模块移动的问题。</p><p>PMO 1.2.0 / Mango Maven 1.0.17 规则升级首次识别出的存量问题，已通过完整 <code>212/212</code> Reactor 报告按 <code>moduleKey</code> 登记为历史债务。<code>debt-budget.json</code> 是数量和 identity 的唯一事实源；每个模块的预算只能下降，不能使用其它模块的减少抵消本模块新增问题。</p><h2 id="更新要求" tabindex="-1">更新要求 <a class="header-anchor" href="#更新要求" aria-label="Permalink to &quot;更新要求&quot;">​</a></h2><ul><li>正向：先完成一次完整 Reactor 架构扫描；schema v2 报告的实际/预期项目数、<code>modules</code> 目录和所有问题 <code>moduleKey</code> 必须完整。再执行 <code>node mango-pmo/tools/check-architecture-debt-budget.mjs --base-ref &quot;$(git merge-base HEAD origin/main)&quot;</code>，同时比较主分支预算、PR 预算和当前报告。</li><li>正向：查看目录聚合债务时执行 <code>node mango-pmo/tools/check-architecture-debt-budget.mjs --module mango-platform/mango-system</code>；查看单模块时可传唯一 artifactId，例如 <code>--module mango-system-core</code>。<code>--module</code> 可重复，所有查询复用同一份全 Reactor 报告。</li><li>正向：某个模块债务减少后执行 <code>node mango-pmo/tools/check-architecture-debt-budget.mjs --module mango-system-core --write</code>，只降低所选模块并重新计算全局聚合；提交前仍须执行无 <code>--module</code> 的全局检查。</li><li>正向：普通 PR 只执行直接改动模块的质量门禁，并用 <code>--baseline-only --base-ref &lt;base-sha&gt;</code> 校验已提交预算未被无授权抬高；完整 212 模块报告只由定时/手工 inventory 或明确的预算迁移生成，不因同一 PR 后续同步而重复扫描。</li><li>禁止：为了让新违规通过而增加全局或模块预算；禁止把问题转移到其它模块、手工修改聚合、使用无法归属的问题、用部分 Reactor 报告写预算，或为每个模块重复运行全量 Maven 构建。</li><li>例外：规则升级确需增加存量预算时，只能在未手工修改原预算的前提下使用完整报告执行全局 <code>--write --accept-increase --reason &quot;&lt;审批原因&gt;&quot;</code>。工具会把原因绑定到原预算 SHA-256；提交后必须用 <code>--base-ref</code> 复验，并取得与仓库 <code>single-owner</code> 或 <code>multi-maintainer</code> 模式一致的授权。合并后该记录作为不可扩张预算的审计证据保留；它不能授权未来增加，未来增加必须绑定新的 base 摘要。模块模式禁止 <code>--accept-increase</code>。</li></ul><p>正例：<code>mango-system-core</code> 从 233 条降到 223 条后，只写回该模块；其它模块不变，全局预算同步减少 10 条，后续检查以新值为上限。</p><p>反例：模块 A 修复一条、模块 B 新增一条后直接写回全局预算。即使总数不变，模块 B 的 identity 增加和模块归属变化也必须失败。</p><p>身份判定示例：历史 PMD 问题因文件前面增加注释从第 20 行移到第 21 行，违规源码行内容未变，仍视为同一历史身份；删除 <code>OldService</code> 的违规却在 <code>NewService</code> 新增同规则违规，会形成一个 identity reduction 和一个 identity increase，必须失败。</p>',8)])])}const b=o(d,[["render",i]]);export{p as __pageData,b as default};
